# PowerShell Script: Apply AuraSound Music Download Pipeline & Auto-Playback Fixes
$ErrorActionPreference = "Stop"

function Write-ProjectFile($relPath, $base64Content) {
  $fullPath = Join-Path (Get-Location) $relPath
  $dir = Split-Path $fullPath -Parent
  if (!(Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  $bytes = [System.Convert]::FromBase64String($base64Content)
  [System.IO.File]::WriteAllBytes($fullPath, $bytes)
  Write-Host "[UPDATED] $relPath" -ForegroundColor Green
}

Write-ProjectFile "src/app/api/tracks/ingest/route.ts" ""
Write-ProjectFile "src/app/api/tracks/stream/route.ts" ""
Write-ProjectFile "src/app/api/tracks/search/route.ts" ""
Write-ProjectFile "src/app/api/tracks/delete/route.ts" ""
Write-ProjectFile "src/components/modals/SmartIngestModal.tsx" ""
Write-ProjectFile "src/store/usePlayerStore.ts" ""
Write-ProjectFile "src/core/types/audio.ts" ""
Write-ProjectFile "src/core/audio/AudioEngine.ts" ""
Write-ProjectFile "src/hooks/useAudioPlayer.ts" ""
Write-ProjectFile ".github/workflows/ingest.yml" ""

Write-Host "`nHoan tat cap nhat tat ca file! Chay npm run build de kiem tra." -ForegroundColor Cyan
